package local.signaltv.app
import org.junit.Assert.*
import org.junit.Test
class SportsTest{
 @Test fun opponentDoesNotGuessNextGame(){val a=InterestTeam("nfl:22","Arizona Cardinals","NFL","ARI","","",listOf("Cardinals"));val b=a.copy(id="nfl:26",name="Seattle Seahawks",aliases=listOf("Seahawks"));val c=a.copy(id="mlb:24",league="MLB",name="St. Louis Cardinals");val catalog=InterestCatalog(listOf(a,b,c),emptyMap());assertEquals(b,sportsOpponent("Cardinals vs. Seahawks",a,catalog));assertNull(sportsOpponent("Cardinals weekly",a,catalog));assertNull(sportsOpponent("Cardinals vs TBD",a,catalog));assertNull(sportsOpponent("Cardinals and Seahawks news",a,catalog))}
 @Test fun missingAndZeroStatsRemainDistinct(){assertEquals("Stats unavailable",sportsCompact(null));val row=SportsRow("x","X","East","2026","Regular season",listOf(SportsStat("wins","Wins","0"),SportsStat("pointsFor","Points For","21")));assertTrue(sportsCompact(row).contains("W: 0"));assertTrue(sportsCompact(row).contains("For: 21"))}

 @Test fun actualGameStatusControlsLive(){val now=1000000L;val g=SportsGame("NFL:1","NFL","A at B",now-1000,true,"pre","STATUS_SCHEDULED","Scheduled",emptyList(),now,false);assertFalse(sportsLive(g,now));assertFalse(sportsLive(g.copy(state="in",status="STATUS_IN_PROGRESS",scheduleOnly=true),now));assertTrue(sportsLive(g.copy(state="in",status="STATUS_IN_PROGRESS"),now));assertFalse(sportsLive(g.copy(state="in",status="STATUS_POSTPONED"),now));assertFalse(sportsLive(g.copy(state="in",status="STATUS_IN_PROGRESS",stale=true),now));assertFalse(sportsLive(g.copy(state="in",status="STATUS_IN_PROGRESS"),now+91000))}
 @Test fun numericSortMissingLastInBothDirections(){fun row(name:String,n:Double?)=SportsRow(name,name,"","","",listOf(SportsStat("v","Value",n.toString(),n)))
 val rows=listOf(row("a",2.0),row("b",10.0),row("c",null),row("d",-2.0));assertEquals(listOf("b","a","d","c"),sportsSort(rows,"v",true).map{it.name});assertEquals(listOf("d","a","b","c"),sportsSort(rows,"v",false).map{it.name})}
 @Test fun candidateChannelsDoNotConfirmLive(){val a=InterestTeam("nfl:22","Arizona Cardinals","NFL","ARI","","",listOf("Cardinals"));val b=a.copy(id="nfl:26",name="Seattle Seahawks",aliases=listOf("Seahawks"));val g=SportsGame("NFL:1","NFL","A at B",1000000,true,"pre","STATUS_SCHEDULED","Scheduled",listOf(SportsCompetitor(a.id,a.name),SportsCompetitor(b.id,b.name)),1000000,false);val channels=listOf(Channel("a","NFL Cardinals"),Channel("b","Arizona Cardinals HD"),Channel("c","General sports"));val hit=InterestHit(channels[2],Programme("Cardinals vs Seahawks",900000,1100000),"sports","",a.id);val catalog=InterestCatalog(listOf(a,b),emptyMap());assertEquals(3,sportsChannels(g,channels,listOf(hit),catalog).size);assertEquals(2,sportsChannels(g,channels,listOf(hit.copy(programme=hit.programme.copy(title="Replay: Cardinals vs Seahawks"))),catalog).size);assertFalse(sportsLive(g,1000000))}
}
